// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(uint16 _feeRate) public {
        // Bound _feeRate to cover both <=5000 and >5000
        uint16 feeRate = uint16(bound(uint256(_feeRate), 0, type(uint16).max));

        address baseToken = address(0x1);
        address nft = address(0x2);
        uint128 virtualBaseTokenReserves = 100;
        uint128 virtualNftReserves = 100;
        uint56 changeFee = 10;
        bytes32 merkleRoot = bytes32(0);
        bool useStolenNftOracle = false;
        bool payRoyalties = false;

        bool ok;
        try c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call attempt, check the invariant:
        // If the call succeeds, feeRate must equal the input feeRate.
        // If the call fails (reverts), feeRate must remain 0 (initial value).
        uint256 storedFeeRate = c.feeRate();

        if (ok) {
            // Successful initialization: feeRate must be the valid input
            assertTrue(storedFeeRate == feeRate);
        } else {
            // Reverted initialization: feeRate must be untouched (0)
            assertTrue(storedFeeRate == 0);
        }
    }
}
